86	  factory Plugin._fromMultiPlatformYaml(
87	    String name,
88	    String path,
89	    dynamic pluginYaml,
90	    List<String> dependencies,
91	  ) {
92	    assert (pluginYaml != null && pluginYaml['platforms'] != null,
93	            'Invalid multi-platform plugin specification $name.');
94	    final YamlMap platformsYaml = pluginYaml['platforms'] as YamlMap;
95	
96	    assert (_validateMultiPlatformYaml(platformsYaml).isEmpty,
97	            'Invalid multi-platform plugin specification $name.');
98	
99	    final Map<String, PluginPlatform> platforms = <String, PluginPlatform>{};
100	
101	    if (_providesImplementationForPlatform(platformsYaml, AndroidPlugin.kConfigKey)) {
102	      platforms[AndroidPlugin.kConfigKey] = AndroidPlugin.fromYaml(
103	        name,
104	        platformsYaml[AndroidPlugin.kConfigKey] as YamlMap,
105	        path,
106	      );
107	    }
108	
109	    if (_providesImplementationForPlatform(platformsYaml, IOSPlugin.kConfigKey)) {
110	      platforms[IOSPlugin.kConfigKey] =
111	          IOSPlugin.fromYaml(name, platformsYaml[IOSPlugin.kConfigKey] as YamlMap);
112	    }
113	
114	    if (_providesImplementationForPlatform(platformsYaml, LinuxPlugin.kConfigKey)) {
115	      platforms[LinuxPlugin.kConfigKey] =
116	          LinuxPlugin.fromYaml(name, platformsYaml[LinuxPlugin.kConfigKey] as YamlMap);
117	    }
118	
119	    if (_providesImplementationForPlatform(platformsYaml, MacOSPlugin.kConfigKey)) {
120	      platforms[MacOSPlugin.kConfigKey] =
121	          MacOSPlugin.fromYaml(name, platformsYaml[MacOSPlugin.kConfigKey] as YamlMap);
122	    }
123	
124	    if (_providesImplementationForPlatform(platformsYaml, WebPlugin.kConfigKey)) {
125	      platforms[WebPlugin.kConfigKey] =
126	          WebPlugin.fromYaml(name, platformsYaml[WebPlugin.kConfigKey] as YamlMap);
127	    }
128	
129	    if (_providesImplementationForPlatform(platformsYaml, WindowsPlugin.kConfigKey)) {
130	      platforms[WindowsPlugin.kConfigKey] =
131	          WindowsPlugin.fromYaml(name, platformsYaml[WindowsPlugin.kConfigKey] as YamlMap);
132	    }
133	
134	    return Plugin(
135	      name: name,
136	      path: path,
137	      platforms: platforms,
138	      dependencies: dependencies,
139	    );
140	  }
